# ====================================================
# scan_uris.map – block typical scanner / probe request paths
# Last updated: 2025-12-30 – maintainer: <your-name>
# ====================================================

# CMS, admin & management panels
# NOTE: /admin/ may collide with Grafana’s internal /admin;
#       review before enabling in production.
"~*/phpmyadmin/"                 1;
"~*/pma/"                        1;
"~*/wp-admin/"                   1;
"~*/wp-login\.php"               1;           # WordPress login【2-0-1】
"~*/xmlrpc\.php"                 1;
"~*/administrator/"              1;           # Joomla admin
"~*/joomla\.xml"                 1;           # Joomla
"~*/admin/"                      1;           # Generic admin panel – SEE NOTE ABOVE
"~*/adminer\.php"                1;           # Adminer DB tool
"~*/manager/html"                1;           # Apache Tomcat manager
"~*/host-manager/html"           1;           # Tomcat host-manager
"~*/hudson/"                     1;
"~*/jenkins/"                    1;
"~*/user/login"                  1;           # Drupal login
"~*/core/CHANGELOG.txt"          1;           # Drupal changelog leak
"~*/downloader"                  1;           # Magento downloader
"~*/app/etc/local.xml"           1;           # Magento config leak
"~*/configuration\.php"          1;           # Joomla configuration leak

# Source-control & metadata leaks
"~*/\.git/?"                     1;
"~*/\.svn/?"                     1;
"~*/\.hg/?"                      1;

# Common file-disclosure & LFI/RFI probes
"~*\.\./\.\./\.\./etc/passwd"    1;
"~*php://filter"                 1;
"~*\.env"                        1;           # Laravel / generic .env【3-0-3】

# Server info & status endpoints
"~*/server-status"               1;
"~*/server-info"                 1;
"~*/status$"                     1;           # Generic /status
"~*/healthcheck"                 1;
"~*/actuator"                    1;           # Spring Boot / Java
"~^/prometheus(?:/|$)"           1;           # NUR /prometheus am Anfang
"~^/metrics(?:/|$)"              1;           # NUR /metrics am Anfang
"~*/jolokia"                     1;           # JMX bridge
"~*/metrics"                     1;           # Generic metrics

# API documentation & development endpoints
# Block auto-generated API docs often exposed in dev/staging
"~*/swagger-ui\.html"            1;           # Swagger UI interface
"~*/swagger\.json"               1;           # Swagger API definition
"~*/api-docs"                    1;           # Generic API documentation
"~*/v2/api-docs"                 1;           # Swagger/OpenAPI v2 docs
"~*/graphql"                     1;           # GraphQL API endpoint

# Directory-listing sort probes
"~*\?C=[NMS];O=[AD]"             1;

# --- Next.js specific paths ---
# These are internal Next.js paths and should not be directly accessible
"~*/_next(?:/|$)"                1; # Catches /_next, /_next/static, /_next/data, etc.
"~*/_react(?:/|$)"               1; # Sometimes used in similar contexts
"~*/_next-live(?:/|$)"           1; # Next.js Live development
"~*/_next-website(?:/|$)"        1; # Next.js related development paths

# --- SDK / Embedded Device Scans ---
"~*/SDK/webLanguage"                                    1;
"~*/goform/goform_get_cmd_process"                      1;
"~*/goform/formJsonAjaxReq"                             1;

# --- Generic Login/Admin Paths (review carefully for false positives) ---
# Only enable if these paths are NOT legitimate for your services.
# Given your setup with /grafana/, /nodered/, /influxdb/, these root paths are likely not legitimate.
"~*/login"                      1; # Generic login page scan
"~*/admin"                      1; # Generic admin page scan


# Alle .env Varianten explizit blocken
"~*/\.env\.backup$"             1;
"~*/\.env\.save$"               1;
"~*/\.env\.sample$"             1;
"~*/\.env\.example$"            1;

